function longestOnes(bits: number[]): number {
  let best = 0;
  for (let i = 0; i < bits.length; i++) {
    let j = i;
    while (j < bits.length && bits[j] === 1) j++;
    best = Math.max(best, j - i);
  }
  return best;
}

